package org.apache.commons.math.geometry;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for Vector3D.distance1 method.
 * distance1 calculates the L1 distance (Manhattan distance): |x2-x1| + |y2-y1| + |z2-z1|
 */
public class Vector3D_distance1_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDistance1_SamePoint() {
        Vector3D v1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D v2 = new Vector3D(1.0, 2.0, 3.0);
        // |1-1| + |2-2| + |3-3| = 0
        assertEquals(0.0, Vector3D.distance1(v1, v2), EPSILON);
    }

    @Test
    public void testDistance1_PositiveDifferences() {
        Vector3D v1 = new Vector3D(1.0, 1.0, 1.0);
        Vector3D v2 = new Vector3D(4.0, 5.0, 6.0);
        // |4-1| + |5-1| + |6-1| = 3 + 4 + 5 = 12
        assertEquals(12.0, Vector3D.distance1(v1, v2), EPSILON);
    }

    @Test
    public void testDistance1_NegativeDifferences() {
        Vector3D v1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D v2 = new Vector3D(-1.0, -2.0, -3.0);
        // |-1-0| + |-2-0| + |-3-0| = 1 + 2 + 3 = 6
        assertEquals(6.0, Vector3D.distance1(v1, v2), EPSILON);
    }

    @Test
    public void testDistance1_MixedSigns() {
        Vector3D v1 = new Vector3D(-5.0, 2.0, 0.0);
        Vector3D v2 = new Vector3D(3.0, -4.0, -1.0);
        // |3 - (-5)| + |-4 - 2| + |-1 - 0| = 8 + 6 + 1 = 15
        assertEquals(15.0, Vector3D.distance1(v1, v2), EPSILON);
    }

    @Test
    public void testDistance1_LargeValues() {
        Vector3D v1 = new Vector3D(1e10, 1e10, 1e10);
        Vector3D v2 = new Vector3D(2e10, 2e10, 2e10);
        // |2e10 - 1e10| * 3 = 3e10
        assertEquals(3e10, Vector3D.distance1(v1, v2), EPSILON);
    }

    @Test
    public void testDistance1_ZeroCoordinates() {
        Vector3D v1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D v2 = new Vector3D(0.0, 0.0, 0.0);
        assertEquals(0.0, Vector3D.distance1(v1, v2), EPSILON);
    }

    @Test
    public void testDistance1_FloatingPointPrecision() {
        Vector3D v1 = new Vector3D(0.1, 0.2, 0.3);
        Vector3D v2 = new Vector3D(0.4, 0.5, 0.6);
        // |0.4-0.1| + |0.5-0.2| + |0.6-0.3| = 0.3 + 0.3 + 0.3 = 0.9
        assertEquals(0.9, Vector3D.distance1(v1, v2), EPSILON);
    }
}
